SELECT A.*, E.name AS emp_name
FROM ATT A
JOIN EMP E ON A.emp_id = E.emp_id
WHERE A.emp_id = #{empId}
AND A.work_date = #{workDate}

SELECT A.*, E.name AS emp_name
FROM ATT A
JOIN EMP E ON A.emp_id = E.emp_id
WHERE A.emp_id = #{empId}
AND A.work_date BETWEEN #{startDate} AND #{endDate}
ORDER BY A.work_date DESC, A.check_in ASC
